object SeedData {
    private const val SEED_TIMESTAMP = 0L

    // Compact builder for the added dhikr below. Arabic is fully vowelled. Every
    // text field is bilingual: the plain field is the English side, the `*Bn`
    // field the Bangla side. `pronunciation` is the Roman-script recitation
    // guide, `pronunciationBn` the same words in Bangla script. `translation` /
    // `translationBn` carry the meaning; `note` / `noteBn` the source, grade and
    // any note on the count. Counts follow an authentic sunnah figure where a
    // hadith fixes one, otherwise the user-supplied number.
    private fun dhikr(
        id: String,
        name: String,
        arabic: String,
        pronunciation: String,
        translation: String,
        lapTarget: Int,
        note: String = "",
        source: String? = null,
        // Bilingual fields. The fully-localized entries pass all four explicitly.
        // The situational-dhikr batches (istighfar / morning / evening / sleep /
        // praise / quranic-dua / salawat / ruqyah / beneficial / surah) were
        // authored before the split: `pronunciation` holds Bangla script and
        // `translation` is "<Bangla> — <English>". For those, leave the *Bn
        // params null and the builder derives both sides.
        nameBn: String? = null,
        pronunciationBn: String? = null,
        translationBn: String? = null,
        noteBn: String? = null,
    ): TasbihEntity {
        // Derive the English/Bangla split for the pre-split batches.
        val enTranslation: String
        val bnTranslation: String
        if (translationBn != null) {
            enTranslation = translation
            bnTranslation = translationBn
        } else {
            val parts = translation.split(" — ", limit = 2)
            if (parts.size == 2) {
                bnTranslation = parts[0]
                enTranslation = parts[1]
            } else {
                enTranslation = translation
                bnTranslation = translation
            }
        }
        // Pre-split batches carry no Roman transliteration; reuse the Bangla
        // script for both recitation guides (same convention as `name()`).
        val bnPronunciation = pronunciationBn ?: pronunciation
        return TasbihEntity(
            id = id,
            name = name,
            nameBn = nameBn ?: name,
            arabic = arabic,
            pronunciation = pronunciation,
            pronunciationBn = bnPronunciation,
            translation = enTranslation,
            translationBn = bnTranslation,
            note = note,
            noteBn = noteBn ?: note,
            source = source,
            lapTarget = lapTarget,
            lapCount = 1,
            isFavorite = false,
            isBuiltIn = true,
            createdAt = SEED_TIMESTAMP,
            updatedAt = SEED_TIMESTAMP,
        )
    }

    private fun name(
        n: Int,
        translit: String,
        arabic: String,
        bangla: String,
        meaningBn: String,
        meaningEn: String,
    ) = TasbihEntity(
        id = "asma_%02d".format(n),
        name = translit,
        nameBn = bangla,
        arabic = arabic,
        pronunciation = translit,
        pronunciationBn = bangla,
        translation = meaningEn,
        translationBn = meaningBn,
        note = "Asma-ul-Husna #$n. From the well-known list of the 99 names of Allah — Jami at-Tirmidhi 3507, Sunan Ibn Majah 3861.",
        noteBn = "আসমাউল হুসনা #$n। ৯৯ নামের প্রসিদ্ধ তালিকা — তিরমিযি ৩৫০৭, ইবনে মাজাহ ৩৮৬১।",
        source = "Jami at-Tirmidhi 3507",
        lapTarget = 3,
        lapCount = 1,
        isFavorite = false,
        isBuiltIn = true,
        createdAt = SEED_TIMESTAMP,
        updatedAt = SEED_TIMESTAMP,
    )

