            note = "মুআওবিযাতাইনের একটি; অন্তরের কুমন্ত্রণা থেকে আশ্রয়। নবি (সাঃ) অসুস্থ হলে এটি ও আল-ফালাক পড়ে শরীরে ফুঁ দিতেন — সহীহ বুখারি ৫০১৬।",
