            note = "নবি (সাঃ) সকাল-সন্ধ্যায় এই দুআ ছাড়তেন না — আবু দাউদ ৫০৯০, আহমাদ ২০৪৩০।",
            source = "Sunan Abi Dawud 5090; Musnad Ahmad 20430",
        ),
