            translation = "আমি আল্লাহর পূর্ণাঙ্গ বাণীসমূহের অসিলায় তাঁর সৃষ্টির অনিষ্ট থেকে আশ্রয় চাই — I seek refuge in Allah's perfect words from the evil of what He has created",
