            translation = "হে আল্লাহ, যেদিন আপনি আপনার বান্দাদের পুনরুত্থিত করবেন সেদিন আপনার শাস্তি থেকে আমাকে রক্ষা করুন — O Allah, protect me from Your punishment on the Day You resurrect Your servants",
