    // Beneficial Dhikr: the 13 rewarded dhikr from the pastebin list, in list
    // order (item 9 splits into two steps). Reused rows: bihamdihi, tahlil_wahdahu,
    // subhan, adada_khalqih, istighfar_sayyid, bihamdihi_azim, baqiyat, hawla,
    // istighfar_qayyum.
    private val beneficialSteps: List<RoutineStepEntity> = listOf(
        "bihamdihi" to 100,
        "tahlil_wahdahu" to 100,
        "tahlil_wahdahu" to 10,
        "subhan" to 100,
        "adada_khalqih" to 3,
        "istighfar_sayyid" to 1,
        "bihamdihi_azim" to 1,
        "baqiyat" to 1,
        "bd_bedouin" to 3,
        "bd_ghfirli_4" to 3,
        "hawla" to 1,
        "bd_salli_muhammad" to 10,
        "istighfar_qayyum" to 3,
        "bd_beloved_words" to 1,
    ).mapIndexed { i, (id, count) ->
        RoutineStepEntity(routineId = "beneficial", tasbihId = id, stepOrder = i, targetCount = count)
    }

    // Ruqyah & Illness: the full sequence from
    // lifewithallah.com/dhikr-dua/main-adhkar/ruqyah-and-illness-quran, in page
    // order. Reused rows: qd_fatihah, kursi, sleep_baqarah_end, morn_3quls,
    // hasbiyallah_arsh, eve_kalimat_tammat.
