    ).mapIndexed { i, (id, count) ->
        RoutineStepEntity(routineId = "ruqyah", tasbihId = id, stepOrder = i, targetCount = count)
    }

    // Salawat: the nine narrated forms of durood from
    // lifewithallah.com/dhikr-dua/main-adhkar/salawat, in page order, once each.
    private val salawatSteps: List<RoutineStepEntity> = (1..9).map { n ->
