    // (28:24), rabbana_atina (2:201), qd/sharh_sadr (20:25-28), parents_rahmah
    // (17:24), sleep_baqarah_end (2:285-6).
    private val quranicDuasSteps: List<RoutineStepEntity> = listOf(
        "qd_fatihah", "istighfar_q_yunus", "istighfar_q_musa", "istighfar_q_adam",
        "istighfar_q_waliyy", "istighfar_q_amanna", "qd_rahimin_109", "istighfar_q_irham",
