        "qd_lut_mufsidin", "qd_zalimin_47", "qd_fitnah_zalimin", "qd_persecution", "qd_ayyub",
        "qd_yusuf", "qd_taqabbal_minna",
    ).mapIndexed { i, id ->
        RoutineStepEntity(routineId = "quranic_duas", tasbihId = id, stepOrder = i, targetCount = 1)
    }

    // Praises of Allah: the full sequence from
    // lifewithallah.com/dhikr-dua/main-adhkar/praises-of-allah, in page order,
    // once each. Reused rows: sleep_rabbas_samawat (#8), sleep_kafani (#11),
    // bihamdihi_azim (#17), adada_khalqih (#18), ism_azam (#29).
    private val praisesSteps: List<RoutineStepEntity> = listOf(
        "praise_q_walad", "praise_q_khalaq", "praise_q_kitab", "praise_q_akhirah", "praise_q_fatir",
        "praise_tahajjud", "praise_uhud", "sleep_rabbas_samawat", "praise_thana_majd", "praise_faqr",
