    }

    // Istighfar: the 9 Qur'anic + 10 sunnah forms from
    // lifewithallah.com/dhikr-dua/main-adhkar/istighfar, in the page's order.
    // Step 13 is the pre-existing `afuww` tasbih (that page's sunnah #4).
    private val istighfarSteps: List<RoutineStepEntity> = listOf(
        "istighfar_q_yunus", "istighfar_q_musa", "istighfar_q_adam", "istighfar_q_waliyy",
        "istighfar_q_amanna", "istighfar_q_irham", "istighfar_q_ilm", "istighfar_q_ikhwan",
        "istighfar_q_nur",
        "istighfar_sayyid", "istighfar_malik", "istighfar_khatiati", "afuww",
        "istighfar_rabba_muhammad", "istighfar_diqqahu", "istighfar_kathira",
        "istighfar_afini", "istighfar_baaid", "istighfar_muminin",
    ).mapIndexed { i, id ->
        RoutineStepEntity(routineId = "istighfar", tasbihId = id, stepOrder = i, targetCount = 3)
    }

    private val coreRoutineSteps: List<RoutineStepEntity> = listOf(
        // Morning/Evening/Before-Sleep Dhikr steps live in `morningSteps`,
        // `eveningSteps` and `beforeSleepSteps` (the full lifewithallah pages).
        // After Salah: matches the prototype's `salah` routine exactly (same 3 steps)
        RoutineStepEntity(routineId = "after_salah", tasbihId = "subhan", stepOrder = 0, targetCount = 33),
        RoutineStepEntity(routineId = "after_salah", tasbihId = "hamd", stepOrder = 1, targetCount = 33),
        RoutineStepEntity(routineId = "after_salah", tasbihId = "akbar", stepOrder = 2, targetCount = 34),
    )

    // Before Sleep: the full sequence from
    // lifewithallah.com/dhikr-dua/main-adhkar/before-sleep, in page order.
    // Replaces the old 2-step stub. The tasbih/tahmid/takbir (Fatimah's dhikr,
    // Bukhari 3705) is the three existing subhan/hamd/akbar rows at 33/33/34.
    private val beforeSleepSteps: List<RoutineStepEntity> = listOf(
        "sleep_sajdah_mulk" to 1,
        "kursi" to 1,
        "sleep_baqarah_end" to 1,
        "sleep_kafirun" to 1,
        "morn_3quls" to 3,
