    }

    // Asma-ul-Husna: walk all 99 names in canonical order, 3 recitations each.
    private val asmaUlHusnaSteps: List<RoutineStepEntity> = (1..99).map { n ->
        RoutineStepEntity(
            routineId = "asma_ul_husna",
            tasbihId = "asma_%02d".format(n),
